raw=sql("WITH s AS (SELECT s.id FROM novel_source_item s JOIN channel_app ca ON ca.id=s.channel_app_id JOIN source_app sa ON sa.id=ca.source_app_id WHERE sa.code='moboreader' AND s.external_agency_id='1351'),p AS (SELECT p.id,p.idempotency_key,p.public_redirect_code,p.status FROM promo_link p JOIN s ON s.id=p.novel_source_item_id),i AS (SELECT i.id,i.status,i.channel_app_id FROM side_effect_intent i WHERE i.promo_link_id IN (SELECT id FROM p) OR (i.target_type='promo_link' AND i.target_id IN (SELECT idempotency_key FROM p))) SELECT json_build_object('samples',(SELECT json_agg(x) FROM (SELECT id,md5(public_redirect_code) AS station_code_md5,status FROM p ORDER BY id LIMIT 3) x),'intents',(SELECT json_agg(i ORDER BY id) FROM i));")
baseline=next(json.loads(x) for x in raw.splitlines() if x.startswith('{'));assert len(baseline['samples'])==3 and baseline['intents']
opdir=pathlib.Path('/opt/cps-novel/shared/operations/plotnovel-opening-2026-10-15');(opdir/'rehome-baseline.json').write_text(json.dumps(baseline,indent=2)+'\n');(opdir/'rehome-baseline.json').chmod(0o600)
backup=json.loads((opdir/'backup.json').read_text());args=['docker','exec','-e','PLOTNOVEL_REHOME_OPERATOR=codex',NAMES['worker'],'tsx','scripts/rehome-plotnovel-source-items.ts','--request-id','plotnovel-rehome-20261015','--reason','v0.6.0 PlotNovel 存量改挂；备份 '+backup['backupId']]
r=run(args,allowed=(0,2));report=json.loads(r.stdout[r.stdout.index('{'):]);print('A4_REHOME_PREVIEW='+json.dumps(report,ensure_ascii=False));print('A4_BASELINE='+json.dumps({'samples':baseline['samples'],'sideEffectIntents':len(baseline['intents'])}));print('A4_BACKUP_ID='+backup['backupId']);assert r.returncode==0 and not report['blocked'] and all(b['total']==0 for b in report['blockers'].values()) and report['blockers']['publishedArticles']['total']==0 and backup['pgRestoreList']=='PASS', 'Owner conditional approval gate failed'
assert report['counts']['sourceItems']==3845 and report['counts']['promoLinks']==2641, 'counts changed; review small-increase authorization before apply'
(opdir/'a4-approved-preview.json').write_text(json.dumps(report,indent=2)+'\n');(opdir/'a4-approved-preview.json').chmod(0o600);print('OWNER_CONDITIONAL_APPROVAL=SATISFIED exact_A2_counts=true');print('PHASE_A=PASS')
